🐛 Describe the bug
Repro
#!/usr/bin/env python3

import torch

src = torch.empty((0, 2, 3), dtype=torch.float16)  # 0 elems
self = torch.empty(1, dtype=torch.complex64)  # 1 elem

print(src.numel())
print(self.numel())

self.real = src # XXX: trigger bug
Details
This repro will call copy_impl, which has a number of calls to fbgemm::Float16ToFloat_simd. On my machine, it goes to:
      } else {
        auto in_data = reinterpret_cast<fbgemm::float16*>(
            src.data_ptr<at::Half>());
        auto* output_ptr = self.data_ptr<float>();
        if (self.numel() < at::internal::GRAIN_SIZE) {
          fbgemm::Float16ToFloat_simd(in_data, output_ptr, self.numel());  // XXX: fails
Which dispatches to:
void Float16ToFloat_simd(const float16* src, float* dst, size_t size) {
  // Run time CPU detection
  if (cpuinfo_initialize()) {
    if (fbgemmHasAvx512Support()) {
      Float16ToFloat_avx512(src, dst, size);
    } else if (fbgemmHasAvx2Support()) {
      Float16ToFloat_avx2(src, dst, size);
    } else {
      Float16ToFloat_ref(src, dst, size);  // XXX: goes here on my machine
      return;
    }
  } else {
    throw std::runtime_error("Failed to initialize cpuinfo!");
  }
}
And finally:
void Float16ToFloat_ref(const float16* src, float* dst, size_t size) {
  for (size_t i = 0; i < size; i++) {
    dst[i] = cpu_half2float(src[i]);  // XXX: bug: assumes that src has enough elems to read from
  }
}
Mitigation
Pass src size to fbgemm functions and check that dst has enough space before calling them.
Notes
I'm currently not planning to verify other fbgemm APIs or different code paths in copy_impl.
